style_new='.filter-head{display:flex;align-items:center;justify-content:space-between;gap:5px}.filter-arrow{border:0;background:transparent;padding:1px 4px;cursor:pointer;color:#667085;font-size:11px}.filter-arrow.active{color:var(--blue);font-weight:700}.filter-popover{position:fixed;z-index:12000;width:260px;max-height:360px;overflow:auto;background:#fff;border:1px solid var(--border);border-radius:8px;box-shadow:0 12px 28px rgba(15,39,64,.18);padding:10px}.filter-popover .option{display:flex;align-items:center;gap:7px;padding:4px 2px;font-size:12px}.filter-popover .option input{width:auto}.filter-actions{display:flex;gap:6px;justify-content:flex-end;margin-top:8px}.saved-views{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 12px}.view-chip{border:1px solid var(--border);background:#fff;padding:6px 9px;border-radius:999px;cursor:pointer;font-size:12px}.view-chip.active{background:var(--nav);color:#fff;border-color:var(--nav)}.util-bar{height:8px;border-radius:99px;background:#eef2f6;overflow:hidden;min-width:110px}.util-bar>span{display:block;height:100%;background:var(--blue)}.ops-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:12px}.ops-grid .card{padding:11px}.link-metric{border:0;background:transparent;color:var(--blue);cursor:pointer;text-decoration:underline;padding:0;font-weight:700}.severity-critical{font-weight:700;color:var(--red)}.severity-high{font-weight:700;color:var(--amber)}'
