adds='''I18N_AR_EN["مركز التحكم اليومي"]="Daily Control Center";I18N_AR_EN["مركز التحكم اليومي للمشرف"]="Supervisor Daily Control Center";I18N_AR_EN["عبء العمل والطاقة"]="Workload & Capacity";I18N_AR_EN["عبء العمل والطاقة الاستيعابية"]="Workload & Capacity";I18N_AR_EN["التعثر والتصعيد"]="Blockers & Escalations";I18N_AR_EN["مركز التعثر والتصعيد"]="Blocker & Escalation Center";I18N_AR_EN["صحة الأتمتة"]="Automation Health";I18N_AR_EN["يعمل الآن على"]="Working Now";I18N_AR_EN["الموعد التالي"]="Next Due";I18N_AR_EN["المتبقي"]="Remaining";I18N_AR_EN["التعثر"]="Blockers";I18N_AR_EN["بانتظار المراجعة"]="Awaiting Review";I18N_AR_EN["تبرير مطلوب"]="Justification Required";I18N_AR_EN["الطاقة اليومية"]="Daily Capacity";I18N_AR_EN["المهام المفتوحة اليوم"]="Open Today";I18N_AR_EN["حرجة"]="Critical";I18N_AR_EN["عالية"]="High";I18N_AR_EN["متعثر"]="Blocked";I18N_AR_EN["الاستخدام"]="Utilization";I18N_AR_EN["إعداد الطاقة"]="Set Capacity";I18N_AR_EN["الخطورة"]="Severity";I18N_AR_EN["منذ"]="Age";I18N_AR_EN["التفاصيل"]="Details";I18N_AR_EN["الأتمتة"]="Automation";I18N_AR_EN["الجدول"]="Schedule";I18N_AR_EN["آخر تشغيل"]="Last Run";I18N_AR_EN["نتيجة آخر تشغيل"]="Last Result";I18N_AR_EN["التشغيل القادم"]="Next Run";I18N_AR_EN["مفقود"]="Missing";I18N_AR_EN["كل المهام"]="All Tasks";I18N_AR_EN["متأخر"]="Overdue";I18N_AR_EN["ينتظر مراجعة المشرف"]="Awaiting Supervisor Review";I18N_AR_EN["عاجل"]="Urgent";I18N_AR_EN["إقفال D+"]="Close D+";I18N_AR_EN["مهامي فقط"]="My Tasks";I18N_AR_EN["إرسال للمراجعة"]="Submit for Review";I18N_AR_EN["اعتماد المهمة"]="Approve Task";I18N_AR_EN["إعادة للعمل"]="Return to Work";I18N_AR_EN["تسجيل تعثر"]="Mark Blocker";I18N_AR_EN["إزالة التعثر"]="Clear Blocker";I18N_AR_EN["قيد المراجعة"]="Under Review";'''
