# Replace old input-row table filtering with header dropdown arrows.
filt_re=r'const tableFilterState=\{\};.*?async function init\(\)'
filt_new=r'''const tableFilterState={};let filterPopover=null;
function installTableFilters(){document.querySelectorAll('.table-wrap table').forEach((table,idx)=>{if(!table.id)table.id=`sanamTable${idx}`;const head=table.tHead;if(!head||!head.rows.length)return;[...head.rows[0].cells].forEach((th,i)=>{if(!th.querySelector('.filter-arrow')){const label=document.createElement('span');while(th.firstChild)label.appendChild(th.firstChild);const wrap=document.createElement('div');wrap.className='filter-head';const btn=document.createElement('button');btn.type='button';btn.className='filter-arrow';btn.textContent='▾';btn.title=currentLang==='en'?'Filter':'فلترة';btn.onclick=e=>{e.stopPropagation();openHeaderFilter(table,i,btn)};wrap.appendChild(label);wrap.appendChild(btn);th.appendChild(wrap)}});applyTableFilters(table)})}
function closeHeaderFilter(){if(filterPopover){filterPopover.remove();filterPopover=null}}
function openHeaderFilter(table,col,btn){closeHeaderFilter();const all=[...table.tBodies].flatMap(b=>[...b.rows]).map(r=>String(r.cells[col]?.innerText||'').trim()).filter(Boolean);const vals=[...new Set(all)].sort((a,b)=>a.localeCompare(b,currentLang==='en'?'en':'ar'));const st=(tableFilterState[table.id]||{})[col]||{text:'',values:[]};const pop=document.createElement('div');pop.className='filter-popover';const search=document.createElement('input');search.type='search';search.placeholder=currentLang==='en'?'Search values':'بحث في القيم';search.value=st.text||'';pop.appendChild(search);const list=document.createElement('div');list.style.marginTop='7px';vals.slice(0,150).forEach(v=>{const lab=document.createElement('label');lab.className='option';const cb=document.createElement('input');cb.type='checkbox';cb.dataset.value=v;cb.checked=(st.values||[]).includes(v);const sp=document.createElement('span');sp.textContent=v;lab.append(cb,sp);list.appendChild(lab)});pop.appendChild(list);const actions=document.createElement('div');actions.className='filter-actions';const clear=document.createElement('button');clear.className='btn';clear.textContent=currentLang==='en'?'Clear':'مسح';clear.onclick=()=>{tableFilterState[table.id]=tableFilterState[table.id]||{};delete tableFilterState[table.id][col];closeHeaderFilter();applyTableFilters(table)};const apply=document.createElement('button');apply.className='btn primary';apply.textContent=currentLang==='en'?'Apply':'تطبيق';apply.onclick=()=>{tableFilterState[table.id]=tableFilterState[table.id]||{};tableFilterState[table.id][col]={text:search.value.trim(),values:[...list.querySelectorAll('input:checked')].map(x=>x.dataset.value)};closeHeaderFilter();applyTableFilters(table)};actions.append(clear,apply);pop.appendChild(actions);search.oninput=()=>{const q=search.value.toLowerCase();list.querySelectorAll('.option').forEach(x=>x.style.display=x.innerText.toLowerCase().includes(q)?'':'none')};document.body.appendChild(pop);const r=btn.getBoundingClientRect();pop.style.top=`${Math.min(r.bottom+4,window.innerHeight-370)}px`;pop.style.left=`${Math.max(8,Math.min(r.left,window.innerWidth-270))}px`;filterPopover=pop;setTimeout(()=>search.focus(),0)}
function applyTableFilters(table){const fs=tableFilterState[table.id]||{};[...table.tBodies].flatMap(b=>[...b.rows]).forEach(r=>{const ok=Object.entries(fs).every(([k,f])=>{const txt=String(r.cells[Number(k)]?.innerText||'').trim();const textOk=!f.text||txt.toLowerCase().includes(String(f.text).toLowerCase());const valuesOk=!f.values?.length||f.values.includes(txt);return textOk&&valuesOk});r.style.display=ok?'':'none'});[...table.tHead.rows[0].cells].forEach((th,i)=>th.querySelector('.filter-arrow')?.classList.toggle('active',!!fs[i]&&(!!fs[i].text||!!fs[i].values?.length)))}
document.addEventListener('click',e=>{if(filterPopover&&!filterPopover.contains(e.target)&&!e.target.closest('.filter-arrow'))closeHeaderFilter()});

async function init()'''
s,n=re.subn(filt_re,lambda m:filt_new,s,count=1,flags=re.S)
if n!=1: raise SystemExit('filter function patch failed')

