# Reload data and render all.
reload_re=r'async function reloadAll\(\)\{.*?\}\nfunction renderAll\(\)\{.*?\}'
reload_new='''async function reloadAll(){const [pr,bk,py,tk,ex,cl,im,pf,ow]=await Promise.all([sb.from("profiles").select("id,email,full_name,role").eq("active",true),sb.from("bank_liquidity").select("*").order("company"),sb.from("payments").select("*,bank_accounts(company,bank_name,account_name)").order("created_at",{ascending:false}),sb.from("tasks").select("*,owner:profiles!tasks_owner_id_fkey(full_name),reviewer:profiles!tasks_reviewer_id_fkey(full_name)").order("due_date",{ascending:false}).order("created_at",{ascending:false}),sb.from("exceptions").select("*,owner:profiles!exceptions_owner_id_fkey(full_name),leave_delegations(*,absent:profiles!leave_delegations_absent_user_id_fkey(full_name),substitute:profiles!leave_delegations_substitute_user_id_fkey(full_name))").order("created_at",{ascending:false}),sb.from("monthly_close_tasks").select("*,owner:profiles!monthly_close_tasks_owner_id_fkey(full_name)").order("due_date").order("code"),sb.from("imprest_funds").select("*,custodian:profiles!imprest_funds_custodian_id_fkey(full_name)").order("created_at",{ascending:false}),sb.rpc("get_finance_team_performance"),sb.from("ownership_matrix").select("*").order("sort_order")]);profiles=pr.data||[];banks=bk.data||[];payments=py.data||[];tasks=tk.data||[];exceptions=ex.data||[];closeTasks=cl.data||[];imprest=im.data||[];performance=pf.data||[];ownership=ow.data||[];if(["CFO","Supervisor"].includes(profile.role)){const [cc,wl,es,ah]=await Promise.all([sb.rpc("get_supervisor_control_center"),sb.rpc("get_workload_capacity"),sb.rpc("get_escalation_center"),sb.rpc("get_automation_health")]);controlCenter=cc.data||[];workload=wl.data||[];escalations=es.data||[];automationHealth=ah.data||[]}else{controlCenter=[];workload=[];escalations=[];automationHealth=[]}renderAll()}
function renderAll(){renderBanks();renderPayments();renderSavedViews();renderTasks();renderControlCenter();renderWorkload();renderEscalations();renderAutomationHealth();renderClose();renderImprest();renderPerformance();renderOwnership();renderExceptions();renderDashboard();installTableFilters();applyLanguage()}'''
s,n=re.subn(reload_re,reload_new,s,count=1,flags=re.S)
if n!=1: raise SystemExit('reload/render patch failed')

# Task logic and Saved Views. Replace from riyadhToday through before openTaskModal.
task_re=r'function riyadhToday\(\).*?function openTaskModal\(\)\{'
task_new=r'''function riyadhToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function taskDeadline(t){if(!t.due_date)return null;return new Date(`${t.due_date}T${t.due_time||'23:59:59'}+03:00`)}
function isTaskOverdue(t){const d=taskDeadline(t);return !!d&&new Date()>d&&!['مكتمل','بانتظار المراجعة'].includes(t.status)&&!t.completed_at}
function taskJustificationRequired(t){return (isTaskOverdue(t)||!!t.justification_requested_at)&&!String(t.delay_justification||'').trim()&&!['مكتمل','بانتظار المراجعة'].includes(t.status)}
const SAVED_VIEWS=[['all','كل المهام'],['today','مهام اليوم'],['overdue','متأخر'],['justification','تبرير مطلوب'],['review','ينتظر مراجعة المشرف'],['urgent','عاجل'],['close','إقفال D+'],['mine','مهامي فقط']];
function renderSavedViews(){if(!document.getElementById('savedViews'))return;savedViews.innerHTML=SAVED_VIEWS.map(([k,l])=>`<button class="view-chip ${activeTaskView===k?'active':''}" onclick="setTaskView('${k}')">${displayText(l)}</button>`).join('')}
function setTaskView(v){if(v==='close'){closeQuickView=true;renderClose();installTableFilters();openPage('close',displayText('الإقفال الشهري'));return}activeTaskView=v;localStorage.setItem('sanam_task_view',v);renderSavedViews();renderTasks();installTableFilters();applyLanguage()}
function taskViewMatches(t){const today=riyadhToday();if(activeTaskView==='today')return t.due_date===today;if(activeTaskView==='overdue')return isTaskOverdue(t);if(activeTaskView==='justification')return taskJustificationRequired(t);if(activeTaskView==='review')return t.status==='بانتظار المراجعة';if(activeTaskView==='urgent')return ['حرج','عالي','عاجل'].includes(t.priority);if(activeTaskView==='mine')return t.owner_id===profile.id;return true}
function taskActionHtml(t){const a=[],mine=t.owner_id===profile.id,reviewer=t.reviewer_id===profile.id||profile.role==='CFO'||(profile.role==='Supervisor'&&t.owner_id!==profile.id);if(mine&&t.opened_at&&!['مكتمل','بانتظار المراجعة'].includes(t.status)){if(t.status!=="قيد التنفيذ")a.push(`<button class="btn" onclick="startTask('${t.id}')">${displayText('بدء')}</button>`);if(t.blocker_note)a.push(`<button class="btn" onclick="clearTaskBlocker('${t.id}')">${displayText('إزالة التعثر')}</button>`);else{a.push(`<button class="btn" onclick="markTaskBlocker('${t.id}')">${displayText('تسجيل تعثر')}</button>`);a.push(`<button class="btn success" onclick="completeTask('${t.id}')">${displayText('إرسال للمراجعة')}</button>`)}}if(mine&&taskJustificationRequired(t))a.push(`<button class="btn danger" onclick="submitTaskJustification('${t.id}')">${displayText('إضافة تبرير')}</button>`);if(profile.role==="Supervisor"&&!['مكتمل','بانتظار المراجعة'].includes(t.status)&&(isTaskOverdue(t)||t.opened_at))a.push(`<button class="btn danger" onclick="requestTaskJustification('${t.id}')">${displayText('طلب تبرير')}</button>`);if(t.status==='بانتظار المراجعة'&&reviewer){a.push(`<button class="btn success" onclick="reviewTask('${t.id}',true)">${displayText('اعتماد المهمة')}</button>`);a.push(`<button class="btn" onclick="reviewTask('${t.id}',false)">${displayText('إعادة للعمل')}</button>`)}return a.join(' ')||'—'}
function renderTasks(){const today=riyadhToday(),todayRows=tasks.filter(t=>t.due_date===today),done=todayRows.filter(t=>t.status==="مكتمل").length,over=todayRows.filter(isTaskOverdue).length,just=todayRows.filter(taskJustificationRequired).length;taskKpis.innerHTML=`<div class="card"><span class="muted">${displayText('مهام اليوم')}</span><b>${todayRows.length}</b></div><div class="card"><span class="muted">${displayText('مكتمل اليوم')}</span><b>${done}</b></div><div class="card"><span class="muted">${displayText('متأخر الآن')}</span><b>${over}</b></div><div class="card"><span class="muted">${displayText('تبريرات معلقة')}</span><b>${just}</b></div>`;const rows=tasks.filter(taskViewMatches);tasksBody.innerHTML=rows.map(t=>{const note=t.blocker_note|| (taskJustificationRequired(t)?displayText('تبرير مطلوب'):(t.delay_justification||t.justification_request_note||t.review_note||'—'));return `<tr class="${isTaskOverdue(t)?'task-overdue':''}"><td>${esc(t.name)}</td><td>${esc(t.owner?.full_name||"—")}</td><td>${esc(t.reviewer?.full_name||"—")}</td><td>${esc(t.due_date||"—")}</td><td>${esc(t.frequency||"—")}</td><td>${esc(t.due_time?String(t.due_time).slice(0,5):"—")}</td><td>${badge(t.priority||"عادي")}</td><td>${badge(t.status||"لم يبدأ")}${t.opened_at&&t.status==="لم يبدأ"?` ${badge('مفتوحة')}`:''}</td><td class="task-control-note">${esc(note)}</td><td>${taskActionHtml(t)}</td></tr>`}).join("")||`<tr><td colspan="10" class="muted">—</td></tr>`;applyTableFilters(document.getElementById('tasksTable'))}
function openDailyPlan(){if(profile.role!=="Supervisor")return;const today=riyadhToday(),rows=tasks.filter(t=>t.frequency==='يومي'&&t.due_date===today&&t.status!=="مكتمل");if(!rows.length){alert(currentLang==='en'?'No daily tasks are available for today.':'لا توجد مهام يومية متاحة لليوم.');return}const html=rows.map(t=>`<tr><td><input type="checkbox" class="plan-check" data-id="${t.id}" checked></td><td>${esc(t.owner?.full_name||'—')}</td><td style="white-space:normal">${esc(t.name)}</td><td>${badge(t.priority||'عادي')}</td><td><input type="time" class="plan-time" data-id="${t.id}" value="${t.due_time?String(t.due_time).slice(0,5):''}"></td></tr>`).join('');showModal(displayText('خطة اليوم / فتح المهام'),`<div class="note" style="margin-bottom:10px">${currentLang==='en'?'Select the tasks to release and set a due time for each selected task.':'حدد المهام التي سيتم فتحها اليوم وضع موعد الاستحقاق لكل مهمة قبل توجيه الفريق.'}</div><div class="table-wrap"><table class="plan-table"><thead><tr><th>✓</th><th>${displayText('المسؤول')}</th><th>${displayText('المهمة')}</th><th>${displayText('الأولوية')}</th><th>${displayText('الوقت')}</th></tr></thead><tbody>${html}</tbody></table></div><div class="row" style="margin-top:14px"><button class="btn success" onclick="saveDailyPlan()">${currentLang==='en'?'Release selected tasks':'فتح المهام المحددة'}</button></div>`)}
async function saveDailyPlan(){const items=[];document.querySelectorAll('.plan-check:checked').forEach(c=>{const id=c.dataset.id,time=document.querySelector(`.plan-time[data-id="${id}"]`)?.value||'';items.push({id,due_time:time})});if(!items.length)return alert(currentLang==='en'?'Select at least one task.':'حدد مهمة واحدة على الأقل.');if(items.some(x=>!x.due_time))return alert(currentLang==='en'?'Due time is required for every selected task.':'يجب تحديد وقت الاستحقاق لكل مهمة محددة.');const {data,error}=await sb.rpc('supervisor_open_daily_plan',{p_items:items});if(error)return alert(error.message);closeModal();await reloadAll();alert(currentLang==='en'?`${data} tasks released.`:`تم فتح ${data} مهمة وتوجيهها للفريق.`)}
async function startTask(id){const {error}=await sb.rpc('start_finance_task',{p_task_id:id});if(error)return alert(error.message);await reloadAll()}
async function markTaskBlocker(id){const note=prompt(currentLang==='en'?'Describe the blocker:':'اكتب سبب التعثر بوضوح:');if(!note||!note.trim())return;const {error}=await sb.rpc('mark_task_blocker',{p_task_id:id,p_note:note.trim()});if(error)return alert(error.message);await reloadAll()}
async function clearTaskBlocker(id){const {error}=await sb.rpc('clear_task_blocker',{p_task_id:id});if(error)return alert(error.message);await reloadAll()}
async function submitTaskJustification(id){const text=prompt(currentLang==='en'?'Enter the required justification:':'اكتب التبرير المطلوب للتأخير أو التعثر:');if(!text||!text.trim())return;const {error}=await sb.rpc('submit_task_justification',{p_task_id:id,p_justification:text.trim()});if(error)return alert(error.message);await reloadAll()}
async function requestTaskJustification(id){const note=prompt(currentLang==='en'?'Reason/note for requesting justification (optional):':'سبب أو ملاحظة طلب التبرير (اختياري):')||'';const {error}=await sb.rpc('request_task_justification',{p_task_id:id,p_note:note});if(error)return alert(error.message);await reloadAll()}
async function completeTask(id){let justification=null;const t=tasks.find(x=>x.id===id);if(t?.blocker_note)return alert(currentLang==='en'?'Clear the blocker before submitting for review.':'يجب إزالة التعثر قبل إرسال المهمة للمراجعة.');if(t&&taskJustificationRequired(t)){justification=prompt(currentLang==='en'?'This task is overdue or has a justification request. Enter justification before submission:':'هذه المهمة متأخرة أو عليها طلب تبرير. يجب إدخال التبرير قبل إرسالها للمراجعة:');if(!justification||!justification.trim())return}let {error}=await sb.rpc('complete_finance_task',{p_task_id:id,p_justification:justification});if(error&&String(error.message||'').includes('DELAY_JUSTIFICATION_REQUIRED')){justification=prompt(currentLang==='en'?'Justification is mandatory before submission:':'التبرير إلزامي قبل إرسال المهمة للمراجعة:');if(!justification||!justification.trim())return;({error}=await sb.rpc('complete_finance_task',{p_task_id:id,p_justification:justification.trim()}))}if(error)return alert(error.message);await reloadAll();alert(currentLang==='en'?'Task submitted for review.':'تم إرسال المهمة للمراجعة.')}
async function reviewTask(id,approve){const note=prompt(approve?(currentLang==='en'?'Review note (optional):':'ملاحظة المراجعة (اختياري):'):(currentLang==='en'?'Reason for returning the task:':'سبب إعادة المهمة للعمل:'))||'';const {error}=await sb.rpc('review_finance_task',{p_task_id:id,p_approve:approve,p_note:note});if(error)return alert(error.message);await reloadAll()}
function openTaskModal(){'''
s,n=re.subn(task_re,lambda m:task_new,s,count=1,flags=re.S)
